"""Commands added so the product works over the CLI and web app (generated by _tools/add_commands.py)."""

import contextlib
import io
import json
import pathlib
import tempfile
import unittest

from agent_telco.__main__ import main

EX = pathlib.Path(__file__).resolve().parent.parent / "examples"


class CommandTests(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self.tmp.cleanup)

    def write(self, obj) -> str:
        path = pathlib.Path(self.tmp.name) / "req.json"
        path.write_text(json.dumps(obj), encoding="utf-8")
        return str(path)

    def run_cli(self, argv):
        out = io.StringIO()
        with contextlib.redirect_stdout(out):
            code = main(argv)
        self.assertIn(code, (0, 1), out.getvalue())
        return json.loads(out.getvalue())

    def test_stop_with_punctuation_opts_out_with_auto_reply(self):
        out = self.run_cli(["inbound", "--body", "Stop!!"])
        self.assertEqual(out["action"], "opt_out")
        self.assertIn("unsubscribed", out["auto_reply"])

    def test_otp_is_extracted_and_quiet_hours_block_marketing(self):
        self.assertEqual(self.run_cli(["inbound", "--body", "Your code is 482913"])["otp"], "482913")
        out = self.run_cli(["send-check", "--body", "Sale", "--marketing", "--local-hour", "22"])
        self.assertFalse(out["allowed"])
        self.assertTrue(self.run_cli(["send-check", "--body", "Your table is ready", "--local-hour", "22"])["allowed"])


if __name__ == "__main__":
    unittest.main()
